ALTER TABLE public.equipment ADD COLUMN repair_content text NOT NULL DEFAULT '', ADD COLUMN assignee text, ADD COLUMN planned_on date, ADD COLUMN stopped boolean NOT NULL DEFAULT false, ADD COLUMN after_breakdown boolean NOT NULL DEFAULT false;
UPDATE public.equipment SET repair_content=COALESCE(NULLIF(btrim(content),''),NULLIF(btrim(name),''),'既存の保全項目');
COMMENT ON COLUMN public.equipment.next_date IS 'DEPRECATED: maintenance next timing is derived from planned_on, cycle and latest history; retained for existing data';
COMMENT ON COLUMN public.equipment.content IS 'DEPRECATED: existing management content preserved; repair_content is the maintenance editing field';
CREATE TABLE public.equipment_names (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.equipment_names TO authenticated;
GRANT INSERT,UPDATE,DELETE ON public.equipment_names TO authenticated;
GRANT ALL ON public.equipment_names TO service_role;
ALTER TABLE public.equipment_names ENABLE ROW LEVEL SECURITY;
CREATE POLICY maintenance_names_read ON public.equipment_names FOR SELECT TO authenticated USING (public.has_perm('equipment'));
CREATE POLICY maintenance_names_admin ON public.equipment_names FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
INSERT INTO public.equipment_names(name) SELECT DISTINCT name FROM public.equipment WHERE NULLIF(btrim(name),'') IS NOT NULL;
CREATE TABLE public.equipment_display_settings (user_id uuid PRIMARY KEY, show_name boolean NOT NULL DEFAULT true, show_assignee boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.equipment_display_settings TO authenticated;
GRANT ALL ON public.equipment_display_settings TO service_role;
ALTER TABLE public.equipment_display_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY maintenance_display_read ON public.equipment_display_settings FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_admin());
CREATE POLICY maintenance_display_admin ON public.equipment_display_settings FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE TABLE public.equipment_history_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), history_id uuid NOT NULL REFERENCES public.equipment_history(id), user_id uuid NOT NULL, photo_id uuid REFERENCES public.photos(id), storage_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.equipment_history_attachments TO authenticated;
GRANT ALL ON public.equipment_history_attachments TO service_role;
ALTER TABLE public.equipment_history_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY maintenance_attachments_read ON public.equipment_history_attachments FOR SELECT TO authenticated USING (public.has_perm('equipment') AND EXISTS (SELECT 1 FROM public.equipment_history h JOIN public.equipment e ON e.id=h.equipment_id WHERE h.id=history_id AND e.deleted_at IS NULL AND h.deleted_at IS NULL AND (e.user_id=auth.uid() OR public.is_admin())));
CREATE POLICY maintenance_attachments_insert ON public.equipment_history_attachments FOR INSERT TO authenticated WITH CHECK (public.has_perm('equipment') AND user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.equipment_history h JOIN public.equipment e ON e.id=h.equipment_id WHERE h.id=history_id AND e.deleted_at IS NULL AND h.deleted_at IS NULL AND (e.user_id=auth.uid() OR public.is_admin())) AND ((photo_id IS NULL AND split_part(storage_path,'/',1)=auth.uid()::text) OR EXISTS (SELECT 1 FROM public.photos p WHERE p.id=photo_id AND p.storage_path=equipment_history_attachments.storage_path AND p.deleted_at IS NULL AND (p.user_id=auth.uid() OR public.is_admin()))));
CREATE OR REPLACE FUNCTION public.maintenance_history_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.equipment e WHERE e.id=NEW.equipment_id AND e.deleted_at IS NULL AND (e.user_id=auth.uid() OR public.is_admin())) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF TG_OP='UPDATE' AND (NEW.equipment_id IS DISTINCT FROM OLD.equipment_id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'History identity cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER maintenance_history_identity BEFORE INSERT OR UPDATE ON public.equipment_history FOR EACH ROW EXECUTE FUNCTION public.maintenance_history_guard();
CREATE OR REPLACE FUNCTION public.maintenance_record_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NULLIF(btrim(NEW.repair_content),'') IS NULL THEN RAISE EXCEPTION 'Repair content is required'; END IF; IF NEW.cycle_value IS NOT NULL AND NEW.cycle_value<1 THEN RAISE EXCEPTION 'Invalid cycle'; END IF; RETURN NEW; END $$;
CREATE TRIGGER maintenance_record_validation BEFORE INSERT OR UPDATE ON public.equipment FOR EACH ROW EXECUTE FUNCTION public.maintenance_record_guard();